/**
 * XML Parser - imports an autounattend.xml back into the configuration model.
 *
 * Understands files generated by this tool and by schneegans.de (embedded <Extensions> scripts),
 * plus the plain FirstLogonCommands format older versions of this tool produced. Every key it
 * sets exists in ConfigModel, so the result can be applied to the form directly.
 */

class XmlParser {
    constructor(xmlString) {
        this.parser = new DOMParser();
        this.doc = this.parser.parseFromString(xmlString, 'application/xml');
        this.config = {};
        this.files = {};
    }

    parse() {
        const parserError = this.doc.querySelector('parsererror');
        if (parserError) throw new Error('Invalid XML: ' + parserError.textContent);

        this.collectFiles();
        this.parseWindowsPE();
        this.parseSpecialize();
        this.parseOobeSystem();
        this.parseScripts();
        this.parseLegacyFirstLogonCommands();
        return this.config;
    }

    /* ------------------------------------------------------------------ helpers */

    text(parent, tagName) {
        if (!parent) return null;
        const el = parent.getElementsByTagName(tagName)[0];
        return el ? el.textContent.trim() : null;
    }

    settings(pass) {
        return Array.from(this.doc.getElementsByTagName('settings')).find(s => s.getAttribute('pass') === pass) || null;
    }

    component(settings, name) {
        if (!settings) return null;
        return Array.from(settings.getElementsByTagName('component')).find(c => c.getAttribute('name') === name) || null;
    }

    file(name) {
        return this.files[name.toLowerCase()] || '';
    }

    has(fileName, needle) {
        return this.file(fileName).includes(needle);
    }

    match(fileName, regex) {
        return regex.exec(this.file(fileName));
    }

    collectFiles() {
        for (const el of Array.from(this.doc.getElementsByTagName('File'))) {
            const path = el.getAttribute('path') || '';
            const name = path.split('\\').pop().toLowerCase();
            this.files[name] = el.textContent.trim();
        }
    }

    /* ------------------------------------------------------------------ passes */

    parseWindowsPE() {
        const c = this.config;
        const pe = this.settings('windowsPE');
        if (!pe) return;

        const archs = new Set(Array.from(pe.getElementsByTagName('component')).map(el => el.getAttribute('processorArchitecture')));
        c.arch_x86 = archs.has('x86');
        c.arch_amd64 = archs.has('amd64');
        c.arch_arm64 = archs.has('arm64');

        const intl = this.component(pe, 'Microsoft-Windows-International-Core-WinPE');
        if (intl) {
            const lang = this.text(intl, 'UILanguage');
            if (lang) c.language = lang;
            const keyboard = this.text(intl, 'InputLocale');
            if (keyboard) c.keyboard = keyboard;
        }

        const setup = this.component(pe, 'Microsoft-Windows-Setup');
        if (!setup) return;

        const key = this.text(setup, 'Key');
        if (key) {
            const generic = XmlParser.GENERIC_KEYS[key];
            if (generic) {
                c.productKeyMode = 'generic';
                c.windowsEdition = generic;
            } else {
                c.productKeyMode = 'custom';
                c.productKey = key;
            }
        } else {
            c.productKeyMode = 'none';
        }

        const diskpart = [];
        for (const cmd of Array.from(setup.getElementsByTagName('RunSynchronousCommand'))) {
            const path = this.text(cmd, 'Path') || '';
            if (path.includes('BypassTPMCheck')) c.bypassTPM = true;
            if (path.includes('BypassSecureBootCheck')) c.bypassSecureBoot = true;
            if (path.includes('BypassRAMCheck')) c.bypassRAM = true;
            if (path.includes('BypassStorageCheck')) c.bypassStorage = true;
            const echo = /diskpart\.txt"? echo (.*)"$/.exec(path);
            if (echo) diskpart.push(echo[1]);
        }

        const disk = setup.getElementsByTagName('DiskConfiguration')[0];
        if (disk) {
            c.partitionMode = 'auto';
            const wipe = this.text(disk, 'WillWipeDisk');
            c.wipeDisk = wipe !== 'false';
            const partitions = Array.from(disk.getElementsByTagName('CreatePartition'));
            const types = partitions.map(p => this.text(p, 'Type'));
            c.partitionStyle = types.includes('EFI') ? 'gpt' : 'mbr';
            const efi = partitions.find(p => this.text(p, 'Type') === 'EFI');
            if (efi && this.text(efi, 'Size')) c.efiSize = parseInt(this.text(efi, 'Size'), 10);
            const recovery = Array.from(disk.getElementsByTagName('ModifyPartition')).find(p => this.text(p, 'TypeID'));
            if (recovery) {
                c.recoveryMode = 'partition';
                const id = this.text(recovery, 'PartitionID');
                const create = partitions.find(p => this.text(p, 'Order') === id);
                if (create && this.text(create, 'Size')) c.recoverySize = parseInt(this.text(create, 'Size'), 10);
            } else {
                c.recoveryMode = 'windows';
            }
        } else if (diskpart.length) {
            c.partitionMode = 'custom';
            c.customDiskPart = diskpart.join('\n');
        } else {
            c.partitionMode = 'interactive';
        }

        const compact = this.text(setup, 'Compact');
        if (compact === 'true') c.compactOS = 'enabled';
        else if (compact === 'false') c.compactOS = 'disabled';
    }

    parseSpecialize() {
        const c = this.config;
        const specialize = this.settings('specialize');
        const shell = this.component(specialize, 'Microsoft-Windows-Shell-Setup');
        if (shell) {
            const name = this.text(shell, 'ComputerName');
            if (name && name !== '*') {
                c.computerNameMode = 'custom';
                c.computerName = name;
            } else {
                c.computerNameMode = 'random';
            }
            const tz = this.text(shell, 'TimeZone');
            if (tz) {
                c.timezoneMode = 'explicit';
                c.timezone = tz;
            }
        }
        const rename = this.match('specialize.ps1', /\$name = & \{\r?\n([\s\S]*?)\r?\n\};\r?\nRename-Computer/);
        if (rename) {
            c.computerNameMode = 'script';
            c.computerNameScript = rename[1].split(/\r?\n/).map(l => l.replace(/^\t\t\t/, '')).join('\n');
        }
    }

    parseOobeSystem() {
        const c = this.config;
        const oobe = this.settings('oobeSystem');
        if (!oobe) return;

        const intl = this.component(oobe, 'Microsoft-Windows-International-Core');
        const geo = this.text(intl, 'GeoID');
        if (geo) c.geoLocation = geo;
        // Since 2025 schneegans puts the locale lines only here, not in the WinPE component
        const keyboard = this.text(intl, 'InputLocale');
        if (keyboard) c.keyboard = keyboard;
        const lang = this.text(intl, 'UILanguage');
        if (lang && !c.language) c.language = lang;

        const shell = this.component(oobe, 'Microsoft-Windows-Shell-Setup');
        if (!shell) return;

        const autoLogonUser = this.text(shell.getElementsByTagName('AutoLogon')[0], 'Username');
        Array.from(shell.getElementsByTagName('LocalAccount')).forEach((account, i) => {
            c[`account_${i}_username`] = this.text(account, 'Name') || '';
            c[`account_${i}_displayname`] = this.text(account, 'DisplayName') || '';
            c[`account_${i}_group`] = this.text(account, 'Group') || 'Users';
            const plain = this.text(account, 'PlainText') !== 'false';
            const value = this.text(account, 'Value') || '';
            c[`account_${i}_password`] = plain ? value : XmlParser.decodePassword(value, 'Password');
            c[`account_${i}_autologon`] = Boolean(autoLogonUser && autoLogonUser === c[`account_${i}_username`]);
        });

        const admin = shell.getElementsByTagName('AdministratorPassword')[0];
        if (admin) {
            c.enableBuiltinAdmin = true;
            const plain = this.text(admin, 'PlainText') !== 'false';
            const value = this.text(admin, 'Value') || '';
            c.builtinAdminPassword = plain ? value : XmlParser.decodePassword(value, 'AdministratorPassword');
        }

        const oobeEl = shell.getElementsByTagName('OOBE')[0];
        if (oobeEl) {
            const protect = this.text(oobeEl, 'ProtectYourPC');
            c.privacySettings = protect === '3' ? 'disable' : protect === '1' ? 'enable' : 'interactive';
            c.hideOnlineAccountScreens = this.text(oobeEl, 'HideOnlineAccountScreens') === 'true';
            const hideWireless = this.text(oobeEl, 'HideWirelessSetupInOOBE') === 'true';
            if (this.file('wifi.xml')) {
                c.wifiMode = 'xml';
                c.wifiXMLProfile = this.file('wifi.xml');
            } else {
                c.wifiMode = hideWireless ? 'skip' : 'interactive';
            }
        }
    }

    /* ----------------------------------------------------------------- scripts */

    parseScripts() {
        const c = this.config;
        if (!Object.keys(this.files).length) return;
        const S = 'specialize.ps1', D = 'defaultuser.ps1', U = 'useronce.ps1', F = 'firstlogon.ps1';

        // Removal lists (schneegans used plural file names until 2025, singular since)
        const selectors = (...names) => names.flatMap(name => Array.from(this.file(name).matchAll(/^\t'([^']+)';$/gm)).map(m => m[1]));
        for (const key of RemovalCatalog.detect(
            selectors('removepackage.ps1', 'removepackages.ps1'),
            selectors('removecapability.ps1', 'removecapabilities.ps1'),
            selectors('removefeature.ps1', 'removefeatures.ps1'))) {
            c[key] = true;
        }
        if (selectors('removecapability.ps1', 'removecapabilities.ps1').includes('Print.Fax.Scan')) c.removeFaxAndScan = true;
        if (this.has(D, 'TurnOffWindowsCopilot') || this.has(U, 'Copilot.Provider')) c.removeCopilot = true;
        if (this.has(S, 'OneDriveSetup.exe') || this.has(D, 'OneDriveSetup')) c.removeOneDrive = true;
        if (this.has(S, '--force-uninstall')) c.removeEdge = true;
        if (this.has(S, 'DevHomeUpdate')) c.removeDevHome = true;
        if (this.has(S, 'OutlookUpdate')) c.removeOutlook = true;
        if (this.has(S, 'ConfigureChatAutoInstall')) c.removeTeams = true;
        if (this.has(D, 'AppCaptureEnabled')) c.removeXboxApps = true;

        // Specialize
        const flags = {
            bypassNRO: [S, 'BypassNRO'],
            disableFastStartup: [S, 'HiberbootEnabled'],
            taskbarHideWidgets: [S, 'AllowNewsAndInterests'],
            disableAppSuggestions: [S, 'DisableWindowsConsumerFeatures'],
            disableDeviceEncryption: [S, 'PreventDeviceEncryption'],
            disableEdgeFirstRun: [S, 'HideFirstRunExperience'],
            disableEdgeStartupBoost: [S, 'StartupBoostEnabled'],
            disableDefender: [S, 'DisableAntiSpyware'],
            disableUpdates: [S, 'NoAutoUpdate'],
            disableAutoReboot: [S, 'NoAutoRebootWithLoggedOnUsers'],
            disableUAC: [S, 'EnableLUA'],
            disableSmartScreen: [S, 'SmartScreenEnabled'],
            disableSmartAppControl: [S, 'VerifiedAndReputablePolicyState'],
            disableCoreIsolation: [S, 'HypervisorEnforcedCodeIntegrity'],
            disableTelemetry: [S, 'AllowTelemetry'],
            enableLongPaths: [S, 'LongPathsEnabled'],
            enableRemoteDesktop: [S, 'fDenyTSConnections'],
            disableSystemRestore: [S, 'Disable-ComputerRestore'],
            optimizeLastAccessTime: [S, 'disablelastaccess'],
            setPowerShellExecutionPolicy: [S, 'Set-ExecutionPolicy'],
            disableAutoSignIn: [S, 'DisableAutomaticRestartSignOn'],
            enableProcessAuditing: [S, 'ProcessCreationIncludeCmdLine_Enabled'],
            enableEdgeUninstall: [S, 'Microsoft Edge" /v NoRemove'],
            disableLockScreen: [S, 'NoLockScreen'],
            customLockScreen: [S, 'LockScreenImage'],
            disableNarrator: [S, 'Narrator.exe'],
            vmVirtualBox: [S, 'VBoxWindowsAdditions.exe'],
            vmVMware: [S, 'REBOOT=R'],
            vmVirtIO: [S, 'virtio-win-guest-tools.exe'],
            vmParallels: [S, 'PTAgent.exe'],
            // Default user
            explorerShowExtensions: [D, 'HideFileExt'],
            explorerShowHidden: [D, '"Hidden" /t REG_DWORD /d 1'],
            taskbarAlignLeft: [D, 'TaskbarAl'],
            disableMouseAcceleration: [D, 'MouseSpeed'],
            taskbarDisableBingSearch: [D, 'DisableSearchBoxSuggestions'],
            explorerClassicContextMenu: [D, '86ca1aa0-34aa-4e8b-a509-50c905bae2a2'],
            explorerEndTaskButton: [D, 'TaskbarEndTask'],
            taskbarHideTaskView: [D, 'ShowTaskViewButton'],
            taskbarHideChat: [D, 'TaskbarMn'],
            taskbarAutoHideTray: [D, 'EnableAutoTray'],
            enableTransparency: [D, 'EnableTransparency'],
            disableSystemSounds: [D, '".None"'],
            // User once
            explorerThisPCView: [U, "'LaunchTo'"],
            // First logon
            cleanupWindowsOld: [F, 'Windows.old'],
        };
        for (const [key, [fileName, needle]] of Object.entries(flags)) c[key] = this.has(fileName, needle);

        if (this.has(D, 'ContentDeliveryManager')) c.disableAppSuggestions = true;

        let m;
        if (this.has(S, 'lockoutthreshold:0')) c.lockoutMode = 'disabled';
        else if ((m = this.match(S, /lockoutthreshold:(\d+) \/lockoutwindow:(\d+) \/lockoutduration:(\d+)/))) {
            c.lockoutMode = 'custom';
            [c.lockoutThreshold, c.lockoutWindow, c.lockoutDuration] = [m[1], m[2], m[3]].map(Number);
        }
        if (this.has(S, 'maxpwage:UNLIMITED')) c.passwordExpiration = 'never';
        else if ((m = this.match(S, /maxpwage:(\d+)/))) { c.passwordExpiration = 'custom'; c.passwordExpirationDays = Number(m[1]); }

        if (this.file('setstartpins.ps1')) {
            const json = (this.match('setstartpins.ps1', /\$json = '([\s\S]*?)';\r?\n/) || [])[1] || '';
            if (json.replace(/\s/g, '') === '{"pinnedList":[]}') c.startPinsWin11 = 'none';
            else { c.startPinsWin11 = 'custom'; c.startPinsWin11JSON = json.replace(/''/g, "'"); }
        }
        if (this.file('layoutmodification.xml')) {
            const xml = this.file('layoutmodification.xml');
            if (xml.replace(/\s/g, '') === ScriptTemplates.layoutModificationEmpty.replace(/\s/g, '')) c.startTilesWin10 = 'none';
            else { c.startTilesWin10 = 'custom'; c.startTilesWin10XML = xml; }
        }

        const effects = Array.from(this.file(S).matchAll(/VisualEffects\\(\w+)" -Name 'DefaultValue' -Value (\d)/g)).map(m => [m[1], Number(m[2])]);
        if (effects.length) {
            const values = new Set(effects.map(e => e[1]));
            if (effects.length >= 17 && values.size === 1 && values.has(0)) c.visualEffectsPreset = 'performance';
            else if (effects.length >= 17 && values.size === 1 && values.has(1)) c.visualEffectsPreset = 'appearance';
            else {
                c.visualEffectsPreset = 'custom';
                for (const [formKey, regKey] of Object.entries(XmlParser.VISUAL_EFFECT_FORM_KEYS)) {
                    const found = effects.find(e => e[0] === regKey);
                    c[formKey] = Boolean(found && found[1] === 1);
                }
            }
        }

        for (const [formKey, name] of Object.entries(XmlParser.START_FOLDERS)) c[formKey] = this.has(S, '/v ' + name + ' ');

        if ((m = this.match(S, /HKU\\\.DEFAULT\\Control Panel\\Keyboard" \/v InitialKeyboardIndicators \/t REG_SZ \/d "(\d+)"/))) {
            const mask = Number(m[1]);
            c.capsLockState = mask & 1 ? 'on' : 'off';
            c.numLockState = mask & 2 ? 'on' : 'off';
            c.scrollLockState = mask & 4 ? 'on' : 'off';
        }

        if ((m = this.match(D, /AppsUseLightTheme \/t REG_DWORD \/d (\d)/))) c.themeMode = m[1] === '0' ? 'dark' : 'light';
        if ((m = this.match(D, /StickyKeys" \/v Flags \/t REG_SZ \/d "(\d+)"/))) {
            const flags = Number(m[1]);
            if (flags === 506) c.stickyKeysMode = 'disabled';
            else {
                c.stickyKeysMode = 'custom';
                c.stickyKeysActivation = Boolean(flags & 4);
                c.stickyKeysConfirm = Boolean(flags & 8);
                c.stickyKeysAudio = Boolean(flags & 16);
                c.stickyKeysIcon = Boolean(flags & 32);
                c.stickyKeysLock = Boolean(flags & 128);
                c.stickyKeysTwoKeys = Boolean(flags & 256);
            }
        }

        if ((m = this.match(U, /SearchboxTaskbarMode' -Type 'DWord' -Value (\d)/))) {
            c.taskbarSearch = ['hide', 'icon', 'box', 'label'][Number(m[1])] || 'default';
        }
        if (this.has(U, 'HideDesktopIcons')) {
            c.desktopIconsMode = 'custom';
            for (const [clsid, formKey] of XmlParser.DESKTOP_ICONS) {
                const found = this.match(U, new RegExp("NewStartPanel' -Name '" + clsid + "' -Value (\\d)"));
                c[formKey] = Boolean(found && found[1] === '0');
            }
        }
        const wallpaper = this.file('setwallpaper.ps1');
        if (wallpaper) {
            if ((m = /Set-WallpaperColor -HtmlColor '(#[0-9a-fA-F]{6})'/.exec(wallpaper))) { c.wallpaperMode = 'solid'; c.wallpaperColor = m[1].toLowerCase(); }
            else if (wallpaper.includes('WriteAllBytes')) c.wallpaperMode = 'custom';
            else if ((m = /Set-WallpaperImage -LiteralPath '((?:[^']|'')*)'/.exec(wallpaper))) { c.wallpaperMode = 'path'; c.wallpaperPath = m[1].replace(/''/g, "'"); }
            const style = /'WallpaperStyle' -Type 'String' -Value '(\d+)'/.exec(wallpaper);
            const tile = /'TileWallpaper' -Type 'String' -Value '(\d)'/.exec(wallpaper);
            if (style) c.wallpaperStyle = tile && tile[1] === '1' ? 'tile' : ({ '10': 'fill', '6': 'fit', '2': 'stretch', '0': 'center', '22': 'span' })[style[1]] || 'fill';
        }
        if ((m = this.match(U, /AccentColorMenu' -Type 'DWord' -Value 0x([0-9a-f]{8})/i))) {
            c.enableCustomAccent = true;
            const v = m[1];
            c.accentColor = '#' + v.slice(6, 8) + v.slice(4, 6) + v.slice(2, 4);
            c.accentOnStartTaskbar = /Personalize' -Name 'ColorPrevalence' -Type 'DWord' -Value 1/.test(this.file(U));
            c.accentOnTitleBars = /DWM' -Name 'ColorPrevalence' -Type 'DWord' -Value 1/.test(this.file(U));
        }

        // Custom scripts: which runner references each unattend-NN.* file decides the phase;
        // several scripts in one phase become <phase>Script, <phase>Script_2, ...
        const phases = [[S, 'system'], [D, 'defaultUser'], [U, 'userOnce'], [F, 'firstLogon']];
        const counts = {};
        for (const name of Object.keys(this.files).sort()) {
            const mm = /^unattend-\d+\.(ps1|cmd|reg|vbs|js)$/.exec(name);
            if (!mm) continue;
            for (const [runner, phase] of phases) {
                if (this.file(runner).toLowerCase().includes(name)) {
                    counts[phase] = (counts[phase] || 0) + 1;
                    const suffix = counts[phase] === 1 ? '' : `_${counts[phase]}`;
                    c[`${phase}ScriptType${suffix}`] = mm[1];
                    c[`${phase}Script${suffix}`] = this.files[name];
                }
            }
        }

        // A file generated by this tool carries its exact configuration in the comment link
        this.applyCommentConfig();
    }

    /** Overlay the configuration encoded in a "#config=" link found in the XML comment, if any. */
    applyCommentConfig() {
        for (const node of Array.from(this.doc.documentElement.childNodes)) {
            if (node.nodeType !== 8) continue;
            const m = /#config=([A-Za-z0-9+/=]+)/.exec(node.nodeValue || '');
            if (!m) continue;
            try {
                Object.assign(this.config, JSON.parse(decodeURIComponent(escape(atob(m[1])))));
            } catch (e) {
                console.warn('Ignoring undecodable configuration link in the XML comment:', e);
            }
        }
    }

    /** Files from older versions of this tool: flat `reg add` commands and a base64 script. */
    parseLegacyFirstLogonCommands() {
        const c = this.config;
        if (Object.keys(this.files).length) return;
        const oobe = this.settings('oobeSystem');
        const shell = this.component(oobe, 'Microsoft-Windows-Shell-Setup');
        if (!shell) return;
        for (const cmd of Array.from(shell.getElementsByTagName('SynchronousCommand'))) {
            const line = this.text(cmd, 'CommandLine') || '';
            if (line.includes('HideFileExt')) c.explorerShowExtensions = true;
            if (line.includes('LaunchTo')) c.explorerThisPCView = true;
            if (line.includes('TaskbarAl')) c.taskbarAlignLeft = true;
            if (line.includes('BingSearchEnabled')) c.taskbarDisableBingSearch = true;
            if (line.includes('HideFirstRunExperience')) c.disableEdgeFirstRun = true;
            if (line.includes('MouseSpeed')) c.disableMouseAcceleration = true;
            if (line.includes('AppsUseLightTheme /t REG_DWORD /d 0')) c.themeMode = 'dark';
            if (line.includes('AppsUseLightTheme /t REG_DWORD /d 1')) c.themeMode = 'light';
            const b64 = /FromBase64String\('([A-Za-z0-9+/=]+)'\)[^']*'[^']*FirstLogon\.(\w+)'/.exec(line);
            if (b64) {
                try {
                    c.firstLogonScriptType = b64[2];
                    c.firstLogonScript = decodeURIComponent(escape(atob(b64[1])));
                } catch (e) { /* ignore undecodable payloads */ }
            }
        }
    }

    static decodePassword(value, suffix) {
        try {
            const decoded = decodeURIComponent(escape(atob(value)));
            return decoded.endsWith(suffix) ? decoded.slice(0, -suffix.length) : decoded;
        } catch (e) {
            return '';
        }
    }
}

